set -e
cd "$(dirname "$0")"
mkdir -p zones/.surl/dns transfers/.surl/dns bad/.surl/dns
cat > zones/.surl/dns/example.com.zone <<'EOF'
$ORIGIN example.com.
$TTL 3600
@     IN SOA   ns1.example.com. admin.example.com. 1 7200 3600 1209600 300
@     IN NS    ns1.example.com.
@     IN MX    10 mail.example.com.
ns1   IN A     127.0.0.1
www   IN A     192.0.2.10
mail  IN A     192.0.2.25
ftp   IN CNAME www
EOF
cat > transfers/.surl/dns/example.com.zone <<'EOF'
$ORIGIN example.com.
$TTL 3600
@     IN SOA   ns1.example.com. admin.example.com. 1 7200 3600 1209600 300
@     IN NS    ns1.example.com.
@     IN MX    10 mail.example.com.
ns1   IN A     127.0.0.1
www   IN A     192.0.2.10
mail  IN A     192.0.2.25
ftp   IN CNAME www
EOF
printf '%s\n' 'this is not a zone' > bad/.surl/dns/example.net.zone
surl --directory zones dns://127.0.0.1:8080/ &
sleep 1
curl dns://127.0.0.1:8080/www.example.com
